"""Render docs/model_report.md from pipeline results (deterministic)."""
from __future__ import annotations

import pandas as pd

from .explain import USE_NOTE
from .features import FEATURES


def _t(header, rows):
    out = ["| " + " | ".join(header) + " |", "|" + "|".join("---" for _ in header) + "|"]
    return "\n".join(out + ["| " + " | ".join(str(x) for x in r) + " |" for r in rows])


def _f(x, d=3):
    return "n/a" if x is None or (isinstance(x, float) and pd.isna(x)) else f"{x:.{d}f}"


def render(R: dict, n_employees: int, seed: int) -> str:
    te, ci, lr = R["test"], R["test_ci"], R["baselines"]["Logistic regression (this model)"]
    coef = R["coefficients"].set_index("feature")["coefficient"]
    base = te["base_rate"]
    ladder = {x["pipeline"]: x for x in R["ladder"]}
    prod = next(v for k, v in ladder.items() if k.startswith("Production"))
    date_only = ladder["Ignore recorded_at (date-only as-of)"]
    naive = ladder["LEAK: latest-value join over all rows"]
    future = ladder["LEAK: latest-value join + count of later snapshots"]
    sub, strat, abl = R["subgroups"], R["stratified"], R["ablation"]
    L = ["# Model Report: Supportive Retention Signals", "",
         f"Synthetic data, seed `{seed}`, `{n_employees:,}` employees. Generated by `python -m yottaflex.model --data data/full --out data/full/model --report docs/model_report.md`.", "",
         "## 1. Headline", "",
         _t(["Question", "Answer"], [
             ["Does it rank better than chance on a future period?", f"Yes, modestly. Test ROC-AUC {te['roc_auc']:.3f} (95% CI {ci['roc_auc'][0]:.3f}-{ci['roc_auc'][1]:.3f}), PR-AUC {te['pr_auc']:.3f} (CI {ci['pr_auc'][0]:.3f}-{ci['pr_auc'][1]:.3f}) against a base rate of {base:.3f}"],
             ["What does a review team get?", f"Reviewing the top 5% of employees finds {te['recall_at_5pct']:.0%} of the people who later left voluntarily ({te['lift_at_5pct']:.1f}x better than random)"],
             ["Is a more complex model better?", f"No. Gradient boosting scores PR-AUC {R['baselines']['Gradient boosting (not interpretable)']['pr_auc']:.3f} against {lr['pr_auc']:.3f} for the explainable model"],
             ["Are leaks caught?", f"Yes. Production pipeline: {prod['provenance_violations']} rows from after the cutoff. The leaky variants fail the audit (see section 5)"],
             ["Is every score explained and reviewable?", "Yes. A guard refuses to emit any row without a plain-language explanation, a reviewer slot, and the supportive framing"],
             ["Any fairness concern?", f"Yes. The top-5% list over-represents long-tenure employees and under-represents first-year employees (section 7). Not fixed silently; a trade-off is shown"]]), "",
         "## 2. What this is, and is not", "",
         f"> {USE_NOTE}", "",
         "- The output is a **priority list for supportive conversations** with HR partners. A person reviews every row.",
         "- It is **not** a prediction that someone will resign, and never an input to pay, promotion, performance or termination decisions.",
         "- Scores are relative priorities. With a 3-4% base rate and ROC-AUC near 0.7, most people on any list will not leave. The reasons shown are what to talk about, not conclusions about the person.", "",
         "## 3. Temporal design", "",
         _t(["Split", "Cutoff (features as of)", "Labels observed until", "Scorable employees", "Voluntary exits", "Base rate", "ROC-AUC", "PR-AUC", "Recall @5%"],
            [[s, v["cutoff"], v["horizon_end"], f"{v['n']:,}", v["positives"], f"{v['base_rate']:.3%}", _f(v["roc_auc"]), _f(v["pr_auc"]), f"{v['recall_at_5pct']:.1%}"] for s, v in R["temporal"].items()]), "",
         "- Train is in-sample, validation is out-of-sample for a train-only fit, **test is out-of-sample for a model fitted on train + validation**. Validation labels are fully observed before the test cutoff.",
         f"- Regularisation `C={R['design']['C']}` was chosen on validation PR-AUC ({', '.join(f'{k}: {v:.4f}' for k, v in R['design']['validation_pr_auc_by_C'].items())}). The differences are tiny, so it is not a sensitive choice.",
         "- Scorable means employed with a snapshot at the cutoff. Voluntary exit within 6 months is the label. Involuntary exits in the horizon are excluded (competing event). Labels are **recomputed** from termination facts, never read from the stored column.",
         "- Split-rule audit: " + ("PASS" if R["audit"]["split"]["ok"] else "FAIL") + f". {R['audit']['split']['rule']}.", "",
         "## 4. Features and results", "",
         f"{len(FEATURES)} features, all computed as of the cutoff from rows recorded by the end of that day: engagement (latest, drop, 4-quarter mean), workload (index, high-load quarters, consecutive **non-peak** overload), career (months since promotion, stagnation beyond 36 months), pay (ratio to band midpoint, gap below 95%), tenure, recent team change or promotion, and a recent retention conversation.",
         "Not used: any sensitive attribute, job family, employment type, team or employee identifiers, any outcome field, and anything from the ground truth.",
         "Missing data: a skipped survey is **missing**, never a score. No survey yet is filled with a neutral 60 plus a flag. The count of skipped surveys is included only so the model can show it carries no negative signal.", "",
         _t(["Model", "ROC-AUC", "PR-AUC", "Recall @5%", "Lift @5%"],
            [[k, _f(v["roc_auc"]), _f(v["pr_auc"]), f"{v['recall_at_5pct']:.1%}", f"{v['lift_at_5pct']:.1f}x"] for k, v in R["baselines"].items()]), "",
         f"The transparent rule row is the documented generator rule without its noise term. It is the best any model could do with these features, so it is a ceiling. The logistic regression sits close to it ({lr['pr_auc']:.3f} vs {R['baselines']['Transparent rule, reference ceiling']['pr_auc']:.3f} PR-AUC); the remaining gap to a perfect score is the unobservable per-employee noise built into the data. This says nothing about real attrition.", "",
         f"Calibration on the test cutoff: Brier {te['brier']:.4f} (a constant base-rate forecast scores {base * (1 - base):.4f}), expected calibration error {te['ece']:.4f}, mean predicted {te['mean_predicted']:.3%} vs observed {base:.3%}. Probabilities are usable as relative scores; skill over the base rate is small.", "",
         _t(["Decile (low to high)", "Employees", "Mean predicted", "Observed rate"],
            [[int(r.bin) + 1, int(r.n), f"{r.mean_predicted:.3%}", f"{r.observed_rate:.3%}"] for r in R["calibration"].itertuples()]), "",
         "### What the model learned", "",
         _t(["Feature (standardised)", "Coefficient", "Odds ratio per 1 SD"], [[r.feature, f"{r.coefficient:+.3f}", f"{r.odds_ratio_per_sd:.2f}"] for r in R["coefficients"].head(12).itertuples()]), "",
         f"The benign cases are close to zero, as designed: planned workload peak `{coef['planned_peak_now']:+.3f}`, recent transfer `{coef['recent_transfer']:+.3f}`, skipped surveys in the last 4 quarters `{coef['surveys_skipped_4q']:+.3f}`. A planned peak, a team move, or a missed survey is not treated as a reason to worry.", "",
         "## 5. Leak audit and the leak ladder", "",
         "The audit checks, on the feature table: (1) **provenance**, meaning the latest `recorded_at` and date among the rows each feature used, which must not exceed the cutoff; (2) no forbidden or sensitive column names; (3) no single feature that separates the outcome with AUC >= 0.90; (4) the split rule; (5) stored labels against recomputed labels. The ladder switches one defence off at a time, on the injected data.", "",
         _t(["Pipeline", "ROC-AUC", "PR-AUC", "Recall @5%", "Rows from after the cutoff", "Audit", "What caught it"],
            [[x["pipeline"], _f(x.get("roc_auc")), _f(x.get("pr_auc")), f"{x['recall_at_5pct']:.1%}", x["provenance_violations"], x["audit"], x["flagged_features"] or ""] for x in R["ladder"]]), "",
         "What this shows:", "",
         f"1. **A small leak can inflate the metric visibly.** Ignoring `recorded_at` touches only {date_only.get('affected_employees', 0)} employees, whose revised rows lift them by {date_only.get('mean_percentile_shift', 0):+.2f} in score percentile, yet PR-AUC moves from {prod['pr_auc']:.3f} to {date_only['pr_auc']:.3f}. Date filtering alone is not enough; availability time matters.",
         f"2. **A leak can also hide.** The latest-value join does not raise the metric (PR-AUC {naive['pr_auc']:.3f}); leavers' latest rows are near the cutoff and stayers' are newer. A metric-only check would pass it. The provenance audit flags {naive['provenance_violations']:,} rows.",
         f"3. **A blatant leak is obvious.** Adding a count of later snapshots gives PR-AUC {future['pr_auc']:.3f}. A result that good is a warning, and the univariate check names the feature.",
         "4. **Data-quality faults are a different layer.** Scoring skipped surveys as zero or trusting a corrupted stored label hurts the metric without any leak. They are caught by the validator (`SURV-SKIPPED-HAS-SCORE`, `RECON-LABEL`), and the production pipeline never depends on either.", "",
         "## 6. Explanations and the output contract", "",
         "Each employee's score is a sum of per-feature contributions to the log-odds relative to the average employee (`coefficient x standardised value`). Features are grouped into plain themes, the top three positive themes are shown with the employee's actual numbers, and survey participation is never listed as a reason.", ""]
    ex = R["signals"].head(3)
    for r in ex.itertuples():
        L += [f"- **Rank {r.rank}, score {r.signal_score:.3f}.** {r.top_factors_text}." + (f" Context: {r.context_notes}." if r.context_notes else "") + f" Suggested topic: {r.suggested_conversation_topic}."]
    sig = R["signals"]
    L += ["", f"`retention_signals.csv` holds the top {R['design']['capacity_fraction']:.0%} ({len(sig)} employees) of the scorable population, the review capacity. Every row carries `human_review_required = True`, `automated_action_allowed = False`, an assigned HR partner, a manager, a `Pending_Review` status with an empty `reviewed_by_employee_id`, the framing note, and a non-empty explanation. `assert_supportive_framing` raises if any row breaks that contract, including decision-style wording such as terminate, dismiss or demote.", "",
          "This is the model-side counterpart to the validator's `unreviewed_individual_score` detector: a score without an explanation or a reviewer cannot be produced.", "",
          "## 7. Sensitive attributes, proxies and subgroup check", "",
          "- No sensitive attribute exists in the data or the features (age, gender, ethnicity, caste, religion, nationality, disability, marital or family status, leave type, home location). A name audit confirms no feature column matches. Job family, employment type, team and level-independent identifiers are kept out of the model as well.",
          "- Tenure, months since promotion and level are job-related and explainable, but in real data they would correlate with age. They are treated as **proxy risks** and monitored below.", "",
          f"Top 5% selection by group on the test cutoff (`monitor` = flag rate outside 0.8x-1.25x of the overall rate, groups of 100 or more):", "",
          _t(["Group", "Value", "Employees", "Attrition vs average", "Flagged vs average", "Precision of flagged", "Monitor"],
             [[r.group, r.value, f"{r.n:,}", f"{r.base_rate_ratio:.2f}x", f"{r.flag_ratio:.2f}x", _f(r.precision_of_flagged), "**yes**" if r.monitor else "no"] for r in sub.itertuples()]), "",
          f"**Finding.** Tenure bands are flagged very unevenly: 7+ years at {sub[sub.value == '7+ years'].flag_ratio.iloc[0]:.2f}x their share although their attrition is {sub[sub.value == '7+ years'].base_rate_ratio.iloc[0]:.2f}x the average, and under 1 year at {sub[sub.value == '<1 year'].flag_ratio.iloc[0]:.2f}x although theirs is {sub[sub.value == '<1 year'].base_rate_ratio.iloc[0]:.2f}x. The model leans on tenure-linked features: removing them ({', '.join(abl['removed'])}) lowers ROC-AUC from {abl['full']['roc_auc']:.3f} to {abl['metrics']['roc_auc']:.3f} and PR-AUC from {abl['full']['pr_auc']:.3f} to {abl['metrics']['pr_auc']:.3f}. In real data, over-flagging long-tenure staff would risk an age proxy.", "",
          "Same review capacity, two ways of spending it:", "",
          _t(["Selection", "Flagged", "Recall", "Precision", "Lift", "Band flag ratio (min-max)"],
             [[k, v["flagged"], f"{v['recall']:.1%}", f"{v['precision']:.1%}", f"{v['lift']:.2f}x", f"{v['min_band_flag_ratio']:.2f}-{v['max_band_flag_ratio']:.2f}"] for k, v in strat.items()]), "",
          "Spending capacity in proportion to each tenure band evens out who is reviewed at a measurable cost in recall. This is a policy choice for HR and legal, so the default stays global ranking with the monitoring above. The fixed 0.8-1.25 band is a screening rule, not a legal test.", "",
          "## 8. Limitations", "",
          "- **Synthetic data.** Performance reflects the generating rule plus noise and says nothing about real attrition. The pipeline, audits and contract are the deliverable.",
          "- **The rule is also the ceiling.** The model is near the transparent rule because that rule produced the labels. A real system would not have this reference.",
          "- **Interventions.** Conversations lower simulated risk, so a good intervention process makes a model look worse over time. The model treats a recent conversation as a feature, not as causal evidence.",
          "- **Leak audit scope.** It checks timestamps and feature provenance inside this dataset. A falsified `recorded_at` would need lineage controls outside it.",
          "- **Fairness scope.** The subgroup check uses job-related groups because no sensitive attribute exists. With real data the same table should be built on protected groups, under legal guidance.",
          "- **Single test period.** One test cutoff with 315 exits gives wide intervals (shown above); differences of a few points between models are not meaningful.", ""]
    return "\n".join(L)
